#!/usr/bin/env bash
#
# Tests the install script's sync logic (the rsync --delete part).
#
# Regression guard for the bug where `tar -xzf ... -C INSTALL_DIR` only adds
# and overwrites files but never deletes files removed from the repo between
# releases. That left stale files (e.g. server/src/bedrock.ts after the
# multi-LLM refactor) in the install dir, breaking the build with TS errors
# about settings keys that no longer exist.
#
# The fix: extract to a staging dir, then rsync --delete into the install dir
# with excludes for data/ (SQLite cache), node_modules/ (regenerated by pnpm),
# and .git/ (dev clones). This test verifies that rsync command does what we
# expect: deletes stale files, preserves excluded dirs.
#
# Run: ./scripts/test-install.bash
#
set -euo pipefail

# ─── Setup: create staging + install dirs ───────────────────────────────────

TMP_ROOT="$(mktemp -d -t llama-install-test-XXXXXX)"
trap 'rm -rf "${TMP_ROOT}"' EXIT

STAGING="${TMP_ROOT}/staging"
INSTALL="${TMP_ROOT}/install"

# Staging dir = what the tarball would extract (the current repo snapshot).
mkdir -p "${STAGING}/server/src" "${STAGING}/client/src" "${STAGING}/scripts"
echo "// current file" > "${STAGING}/server/src/index.ts"
echo "// current file" > "${STAGING}/server/src/llms.ts"
echo "<html>current</html>" > "${STAGING}/client/src/App.tsx"
echo "#!/usr/bin/env bash" > "${STAGING}/scripts/install.bash"

# Install dir = the user's existing install, with stale files + preserved dirs.
mkdir -p "${INSTALL}/server/src" "${INSTALL}/client/src" "${INSTALL}/scripts"
mkdir -p "${INSTALL}/data" "${INSTALL}/node_modules/foo" "${INSTALL}/.git"

# Stale file: exists in install but NOT in staging (the bug — should be deleted).
echo "// stale file referencing deleted settings keys" > "${INSTALL}/server/src/bedrock.ts"

# Current file: exists in both (should be overwritten with staging's version).
echo "// old version" > "${INSTALL}/server/src/index.ts"

# Preserved dirs: should survive the sync.
echo "sqlite cache" > "${INSTALL}/data/explorer.db"
echo "node_modules content" > "${INSTALL}/node_modules/foo/index.js"
echo "git config" > "${INSTALL}/.git/config"

# ─── Run the sync command (same as install.bash) ────────────────────────────

echo "==> Running rsync --delete sync..."
rsync -a --delete \
  --exclude='/data' \
  --exclude='/node_modules' \
  --exclude='/.git' \
  "${STAGING}/" "${INSTALL}/"

# ─── Assertions ─────────────────────────────────────────────────────────────

PASS=0
FAIL=0

assert_exists() {
  local desc="$1"
  local path="$2"
  if [[ -e "${path}" ]]; then
    echo "  ✓ ${desc}"
    PASS=$((PASS + 1))
  else
    echo "  ✗ ${desc} — expected ${path} to exist" >&2
    FAIL=$((FAIL + 1))
  fi
}

assert_not_exists() {
  local desc="$1"
  local path="$2"
  if [[ ! -e "${path}" ]]; then
    echo "  ✓ ${desc}"
    PASS=$((PASS + 1))
  else
    echo "  ✗ ${desc} — expected ${path} to NOT exist" >&2
    FAIL=$((FAIL + 1))
  fi
}

assert_content() {
  local desc="$1"
  local path="$2"
  local expected="$3"
  local actual
  actual="$(cat "${path}")"
  if [[ "${actual}" == "${expected}" ]]; then
    echo "  ✓ ${desc}"
    PASS=$((PASS + 1))
  else
    echo "  ✗ ${desc} — expected ${path} to contain '${expected}', got '${actual}'" >&2
    FAIL=$((FAIL + 1))
  fi
}

echo ""
echo "=== Stale file removal ==="
assert_not_exists "stale server/src/bedrock.ts is deleted" "${INSTALL}/server/src/bedrock.ts"

echo ""
echo "=== Current files synced from staging ==="
assert_exists "server/src/index.ts exists" "${INSTALL}/server/src/index.ts"
assert_content "server/src/index.ts is updated to staging version" "${INSTALL}/server/src/index.ts" "// current file"
assert_exists "server/src/llms.ts exists (new file from staging)" "${INSTALL}/server/src/llms.ts"
assert_exists "client/src/App.tsx exists" "${INSTALL}/client/src/App.tsx"
assert_exists "scripts/install.bash exists" "${INSTALL}/scripts/install.bash"

echo ""
echo "=== Excluded dirs preserved ==="
assert_exists "data/explorer.db is preserved" "${INSTALL}/data/explorer.db"
assert_content "data/explorer.db content is intact" "${INSTALL}/data/explorer.db" "sqlite cache"
assert_exists "node_modules/foo is preserved" "${INSTALL}/node_modules/foo/index.js"
assert_content "node_modules content is intact" "${INSTALL}/node_modules/foo/index.js" "node_modules content"
assert_exists ".git/config is preserved" "${INSTALL}/.git/config"
assert_content ".git/config content is intact" "${INSTALL}/.git/config" "git config"

echo ""
echo "=== Summary ==="
echo "  ${PASS} passed, ${FAIL} failed"

if [[ ${FAIL} -gt 0 ]]; then
  echo ""
  echo "FAIL: install script sync regression — stale files not cleaned up properly." >&2
  exit 1
fi

echo ""
echo "✓ All install script sync tests passed."
